var xml = msg.payload;

var result = {
    status: 'success',
    data: {
        timestamp: new Date().toISOString(),
        timestamp_local: new Date().toLocaleString('zh-HK', {
            timeZone: 'Asia/Hong_Kong',
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
        }),
        journeys: [],
        statistics: {
            total: 0,
            avg_time: 0,
            min_time: 9999,
            max_time: 0
        }
    }
};

var journeyPattern = /<jtis_journey_time[^>]*>[\s\S]*?<\/jtis_journey_time>/gi;
var journeyMatches = xml.match(journeyPattern);

if (journeyMatches) {
    journeyMatches.forEach(function (journeyXml) {
        var journey = {};
        var locMatch = journeyXml.match(/<LOCATION_ID>([\s\S]*?)<\/LOCATION_ID>/i);
        var destMatch = journeyXml.match(/<DESTINATION_ID>([\s\S]*?)<\/DESTINATION_ID>/i);
        var dateMatch = journeyXml.match(/<CAPTURE_DATE>([\s\S]*?)<\/CAPTURE_DATE>/i);
        var typeMatch = journeyXml.match(/<JOURNEY_TYPE>([\s\S]*?)<\/JOURNEY_TYPE>/i);
        var timeMatch = journeyXml.match(/<JOURNEY_DATA>([\s\S]*?)<\/JOURNEY_DATA>/i);
        var colorMatch = journeyXml.match(/<COLOUR_ID>([\s\S]*?)<\/COLOUR_ID>/i);
        var descMatch = journeyXml.match(/<JOURNEY_DESC>([\s\S]*?)<\/JOURNEY_DESC>/i);
        journey.location_id = locMatch ? locMatch[1].trim() : '';
        journey.destination_id = destMatch ? destMatch[1].trim() : '';
        journey.capture_date = dateMatch ? dateMatch[1].trim() : '';
        journey.journey_type = typeMatch ? typeMatch[1].trim() : '';
        journey.journey_data = timeMatch ? timeMatch[1].trim() : '';
        journey.colour_id = colorMatch ? colorMatch[1].trim() : '';
        journey.journey_desc = descMatch ? descMatch[1].trim() : '';
        var timeValue = parseInt(journey.journey_data);
        if (!isNaN(timeValue)) {
            journey.time_minutes = timeValue;
            result.data.statistics.total++;
            result.data.statistics.avg_time += timeValue;
            if (timeValue < result.data.statistics.min_time) {
                result.data.statistics.min_time = timeValue;
            }
            if (timeValue > result.data.statistics.max_time) {
                result.data.statistics.max_time = timeValue;
            }
        }

        var freeFlowTime = 5;
        var tti = timeValue / freeFlowTime;
        var tci = Math.min(tti - 1, 1.0); 
        journey.tci = Math.max(0, Math.min((timeValue - freeFlowTime) / freeFlowTime, 1.0));

        result.data.journeys.push(journey);
    });
}

if (result.data.statistics.total > 0) {
    result.data.statistics.avg_time = Math.round(result.data.statistics.avg_time / result.data.statistics.total);
} else {
    result.data.statistics.min_time = 0;
}

result.data.journeys.sort(function (a, b) {
    return (a.time_minutes || 9999) - (b.time_minutes || 9999);
});

msg.payload = result;
return msg;

flow.set('journey_time_data', msg.payload);
var stats = msg.payload.data.statistics;
node.warn('[JSS] Journey time updated: ' + stats.total + ' routes, avg ' + stats.avg_time + ' min');
return msg;

var data = flow.get('journey_time_data');
if (!data) {
    msg.payload = { status: 'error', message: 'No data available' };
    msg.statusCode = 503;
} else {
    msg.payload = data;
    msg.statusCode = 200;
}
return msg;

