<body>
    <div class="container">
        <div class="header">
            <h1>🚗 香港行車時間</h1>
            <p>HONG KONG JOURNEY TIME · REAL-TIME</p>
            <div class="data-source-badge">數據來源：運輸署行車時間服務 | 自動刷新 60秒</div>
            <div class="live-badge">● 實時直播</div>
            <div><button class="refresh-btn" onclick="fetchJourneyTimeData()">⟳ 手動刷新</button></div>
        </div>

        <div id="stats">
            <div class="loading">⏳ 加載行車數據中...</div>
        </div>

        <div class="filter-section" id="filter-section" style="display:none;">
            <div class="filter-label">📍 按起點篩選 / Filter by Origin</div>
            <div class="filter-buttons" id="location-filters">
                <button class="filter-btn active" data-location="all">全部 All</button>
            </div>
        </div>

        <h2 class="section-title">📋 實時行車路線</h2>
        <div id="journeys"></div>

        <div class="meta" id="meta"></div>
    </div>

    <script>
        let currentFilter = "all";
        let allData = null;

        function calculateStatistics(journeys) {
            if (!journeys || journeys.length === 0) {
                return { total: 0, avg_time: 0, min_time: 0, max_time: 0 };
            }
            const times = journeys.map(j => parseInt(j.time_minutes) || parseInt(j.journey_data) || 0);
            const total = journeys.length;
            const avg_time = Math.round(times.reduce((a, b) => a + b, 0) / total);
            const min_time = Math.min(...times);
            const max_time = Math.max(...times);
            return { total, avg_time, min_time, max_time };
        }

        async function fetchJourneyTimeData() {
            console.log("Fetching journey time data...");
            const statsDiv = document.getElementById("stats");
            try {
                const response = await fetch("/journey-time");
                if (!response.ok) throw new Error("HTTP error: " + response.status);
                const result = await response.json();

                if (result.status === "success") {
                    allData = result;
                    if (!result.data.statistics) {
                        result.data.statistics = calculateStatistics(result.data.journeys);
                    }
                    displayDashboard(result.data);
                } else {
                    statsDiv.innerHTML = '<div class="error-message">❌ 數據加載失敗: ' + (result.message || '未知錯誤') + '</div>';
                }
            } catch (error) {
                console.error("Fetch error:", error);
                statsDiv.innerHTML = '<div class="error-message">🌐 網絡錯誤: ' + error.message + '</div>';
            }
        }

        function displayDashboard(data) {
            if (!data || !data.journeys) {
                document.getElementById("stats").innerHTML = '<div class="error-message">📭 數據格式異常</div>';
                return;
            }

            const stats = data.statistics || calculateStatistics(data.journeys);

            const statsHtml = '<div class="stats-grid">' +
                '<div class="stat-card total"><div class="stat-value">' + stats.total + '</div><div class="stat-label">總數 Total</div></div>' +
                '<div class="stat-card avg"><div class="stat-value">' + stats.avg_time + '</div><div class="stat-label">平均分鐘 Avg</div></div>' +
                '<div class="stat-card min"><div class="stat-value">' + stats.min_time + '</div><div class="stat-label">最短 Min</div></div>' +
                '<div class="stat-card max"><div class="stat-value">' + stats.max_time + '</div><div class="stat-label">最長 Max</div></div>' +
                '</div>';
            document.getElementById("stats").innerHTML = statsHtml;

            // 提取起點列表
            const locations = [...new Set(data.journeys.map(j => j.location_id).filter(l => l && l !== 'null'))];
            let filterHtml = '<button class="filter-btn ' + (currentFilter === "all" ? "active" : "") + '" data-location="all" onclick="handleFilterClick(event)">全部 All</button>';
            locations.forEach(loc => {
                filterHtml += '<button class="filter-btn ' + (currentFilter === loc ? "active" : "") + '" data-location="' + loc.replace(/'/g, "\\'") + '" onclick="handleFilterClick(event)">' + loc + '</button>';
            });
            document.getElementById("location-filters").innerHTML = filterHtml;
            document.getElementById("filter-section").style.display = "block";

            const filtered = currentFilter === "all" ? data.journeys : data.journeys.filter(j => j.location_id === currentFilter);
            const journeysDiv = document.getElementById("journeys");

            if (filtered.length === 0) {
                journeysDiv.innerHTML = '<div style="text-align:center;color:#5f9dbb;padding:40px;">🚧 暫無匹配的行車路線</div>';
                return;
            }

            let journeysHtml = '<div class="journeys-grid">';
            filtered.forEach(journey => {
                const timeValue = parseInt(journey.journey_data) || 0;
                let timeColor = "#4CAF50";
                if (timeValue > 20) timeColor = "#f44336";
                else if (timeValue > 10) timeColor = "#FF9800";

                let statusText = "";
                if (journey.colour_id === "1") statusText = "🟢 暢通";
                else if (journey.colour_id === "2") statusText = "🟡 緩慢";
                else if (journey.colour_id === "3") statusText = "🔴 擁堵";
                else statusText = "⚪ 未知";

                journeysHtml += '<div class="journey-card">' +
                    '<div class="journey-header">' +
                    '<span class="journey-route">' + (journey.location_id || '?') + ' → ' + (journey.destination_id || '?') + '</span>' +
                    '<span class="journey-time" style="color:' + timeColor + '">' + journey.journey_data + '<span class="unit">min</span></span>' +
                    '</div>' +
                    '<div class="journey-meta">' +
                    '<div class="journey-meta-item"><span class="journey-meta-label">起點:</span> ' + (journey.location_id || '-') + '</div>' +
                    '<div class="journey-meta-item"><span class="journey-meta-label">終點:</span> ' + (journey.destination_id || '-') + '</div>' +
                    '<div class="journey-meta-item"><span class="journey-meta-label">預計用時:</span> ' + journey.journey_data + ' 分鐘</div>' +
                    '<div class="journey-meta-item"><span class="journey-meta-label">路況:</span> ' + statusText + '</div>' +
                    '<div class="journey-meta-item"><span class="journey-meta-label">數據時間:</span> ' + (journey.capture_date ? new Date(journey.capture_date).toLocaleString('zh-CN') : '-') + '</div>' +
                    '</div></div>';
            });
            journeysHtml += '</div>';
            journeysDiv.innerHTML = journeysHtml;

            const timeStr = data.timestamp_local ? new Date(data.timestamp_local).toLocaleString('zh-CN') : new Date().toLocaleString();
            document.getElementById("meta").innerHTML = '🕒 最後更新: ' + timeStr + ' | 共 ' + stats.total + ' 條路線 | 每60秒自動刷新';
        }

        function handleFilterClick(event) {
            const location = event.currentTarget.dataset.location;
            if (!location) return;
            currentFilter = location;
            if (allData) {
                const dataCopy = allData.data;
                if (!dataCopy.statistics) {
                    dataCopy.statistics = calculateStatistics(dataCopy.journeys);
                }
                displayDashboard(dataCopy);
            }
            // 更新按鈕樣式
            document.querySelectorAll('.filter-btn').forEach(btn => {
                if (btn.dataset.location === location) btn.classList.add('active');
                else btn.classList.remove('active');
            });
        }

        fetchJourneyTimeData();
        setInterval(fetchJourneyTimeData, 60000);
    </script>
</body>
</html>`;

msg.payload = html;
msg.headers = {
    'Content-Type': 'text/html; charset=utf-8'
};

return msg;

