        var detailEnMatch = messageXml.match(/<INCIDENT_DETAIL_EN>([^<]*)<\/INCIDENT_DETAIL_EN>/);
        var detailCnMatch = messageXml.match(/<INCIDENT_DETAIL_CN>([^<]*)<\/INCIDENT_DETAIL_CN>/);
