// Parse Real SLP XML Data to JSON (without external modules)
var xmlString = msg.payload;

// Simple XML parser function
function parseXML(xmlString) {
    var result = {};
    var detectors = [];

    // Extract date
    var dateMatch = xmlString.match(/<date>([^<]+)<\/date>/);
    if (dateMatch) {
        result.date = dateMatch[1];
    }

    // Extract period
    var periodFromMatch = xmlString.match(/<period_from>([^<]+)<\/period_from>/);
    var periodToMatch = xmlString.match(/<period_to>([^<]+)<\/period_to>/);
    if (periodFromMatch && periodToMatch) {
        result.period = {
            from: periodFromMatch[1],
            to: periodToMatch[1]
        };
    }

    // Extract all detectors
    var detectorRegex = /<detector>([\s\S]*?)<\/detector>/g;
    var detectorMatch;

    while ((detectorMatch = detectorRegex.exec(xmlString)) !== null) {
        var detectorXml = detectorMatch[1];

        var detector = {};

        // Extract detector_id
        var idMatch = detectorXml.match(/<detector_id>([^<]+)<\/detector_id>/);
        if (idMatch) {
            detector.detector_id = idMatch[1];
            detector.device_id = idMatch[1];
        }

        // Extract direction
        var dirMatch = detectorXml.match(/<direction>([^<]+)<\/direction>/);
        if (dirMatch) {
            detector.direction = dirMatch[1];
        }

        // Extract lanes
        var lanes = [];
        var laneRegex = /<lane>([\s\S]*?)<\/lane>/g;
        var laneMatch;

        while ((laneMatch = laneRegex.exec(detectorXml)) !== null) {
            var laneXml = laneMatch[1];

            var lane = {};

            // Lane ID
            var laneIdMatch = laneXml.match(/<lane_id>([^<]+)<\/lane_id>/);
            if (laneIdMatch) {
                lane.lane_id = laneIdMatch[1];
                lane.lane_name = laneIdMatch[1];
            }

            // Speed
            var speedMatch = laneXml.match(/<speed>([^<]+)<\/speed>/);
            if (speedMatch) {
                lane.speed = parseInt(speedMatch[1]) || 0;
            } else {
                lane.speed = 0;
            }

            // Occupancy
            var occMatch = laneXml.match(/<occupancy>([^<]+)<\/occupancy>/);
            if (occMatch) {
                lane.occupancy = parseInt(occMatch[1]) || 0;
            } else {
                lane.occupancy = 0;
            }

            // Volume
            var volMatch = laneXml.match(/<volume>([^<]+)<\/volume>/);
            if (volMatch) {
                lane.volume = parseInt(volMatch[1]) || 0;
            } else {
                lane.volume = 0;
            }

            // Standard Deviation
            var sdMatch = laneXml.match(/<s\.d\.>([^<]+)<\/s\.d\.>/);
            if (sdMatch) {
                lane.sd = parseFloat(sdMatch[1]).toFixed(1) || "0.0";
            } else {
                lane.sd = "0.0";
            }

            // Valid
            var validMatch = laneXml.match(/<valid>([^<]+)<\/valid>/);
            if (validMatch) {
                lane.valid = validMatch[1];
            } else {
                lane.valid = "N";
            }

            lanes.push(lane);
        }

        detector.lanes = lanes;
        detector.lane_count = lanes.length;

        // Calculate detector stats
        var validLanes = lanes.filter(function(l) { return l.valid === 'Y'; });
        detector.is_online = validLanes.length > 0;

        if (validLanes.length > 0) {
            var totalSpeed = validLanes.reduce(function(sum, l) { return sum + l.speed; }, 0);
            detector.avg_speed = Math.round(totalSpeed / validLanes.length);
            detector.total_volume = validLanes.reduce(function(sum, l) { return sum + l.volume; }, 0);
        } else {
            detector.avg_speed = 0;
            detector.total_volume = 0;
        }

        detectors.push(detector);
    }

    result.detectors = detectors;
    return result;
}

// Parse the XML
var raw = parseXML(xmlString);

// Calculate overall statistics
var detectors = raw.detectors || [];
var total_lanes = 0;
var all_speeds = [];
var all_occupancies = [];
var all_volumes = [];
var online_count = 0;

for (var i = 0; i < detectors.length; i++) {
    var det = detectors[i];

    if (det.is_online) {
        online_count++;

        for (var j = 0; j < det.lanes.length; j++) {
            var lane = det.lanes[j];
            if (lane.valid === 'Y') {
                total_lanes++;
                all_speeds.push(lane.speed);
                all_occupancies.push(lane.occupancy);
                all_volumes.push(lane.volume);
            }
        }
    }
}

var overall_avg_speed = all_speeds.length > 0 ?
    Math.round(all_speeds.reduce(function(a, b) { return a + b; }, 0) / all_speeds.length) : 0;

var overall_avg_occupancy = all_occupancies.length > 0 ?
    Math.round(all_occupancies.reduce(function(a, b) { return a + b; }, 0) / all_occupancies.length) : 0;

var overall_total_volume = all_volumes.reduce(function(a, b) { return a + b; }, 0);

var traffic_data = {
    timestamp: new Date().toISOString(),
    timestamp_local: new Date().toLocaleString('zh-HK'),
    date: raw.date || '',
    period: raw.period || {},
    detectors: detectors,
    statistics: {
        total_detectors: detectors.length,
        online_detectors: online_count,
        offline_detectors: detectors.length - online_count,
        total_lanes: total_lanes,
        avg_speed: overall_avg_speed,
        avg_occupancy: overall_avg_occupancy,
        total_volume: overall_total_volume,
        max_speed: all_speeds.length > 0 ? Math.max.apply(null, all_speeds) : 0,
        min_speed: all_speeds.length > 0 ? Math.min.apply(null, all_speeds) : 0
    },
    meta: {
