        format: 'XML',
        update_interval: '30 seconds',
        last_updated: new Date().toISOString()
    }
};

// Store in global context
global.set('slp_real_data', traffic_data);
global.set('slp_real_last_update', new Date().toISOString());

msg.payload = traffic_data;
