    var day = ts.getDay();
    var isWeekday = (day >= 1 && day <= 5) ? 1 : 0;
    var isPeak = (hour >= 7 && hour <= 9) || (hour >= 17 && hour <= 19) ? 1 : 0;
    var temperature = weatherData.temperature != null ? weatherData.temperature : 25;
    var humidity = weatherData.humidity != null ? weatherData.humidity : 70;
    var activeIncidents = trafficNews.statistics ? trafficNews.statistics.active : 0;

    dataPoints.push({
        timestamp: ts.getTime(),
        hour: hour,
        features: [1, hour, isWeekday, isPeak, temperature, humidity, activeIncidents],
        target: avgTime
    });
});

dataPoints.sort(function(a, b) { return a.timestamp - b.timestamp; });

node.warn('[預測] 有效歷史數據點: ' + dataPoints.length);

var prediction = {
    hasData: false,
    forecastValue: null,
    forecastTime: null,
    method: 'none'
};

var futureTime = new Date(Date.now() + 60 * 60 * 1000);
var futureHour = futureTime.getHours();
var futureDay = futureTime.getDay();
var futureIsWeekday = (futureDay >= 1 && futureDay <= 5) ? 1 : 0;
var futureIsPeak = (futureHour >= 7 && futureHour <= 9) || (futureHour >= 17 && futureHour <= 19) ? 1 : 0;
var futureTemp = weatherData.temperature != null ? weatherData.temperature : 25;
var futureHum = weatherData.humidity != null ? weatherData.humidity : 70;
var futureIncidents = trafficNews.statistics ? trafficNews.statistics.active : 0;

// ----- 模型 1：多元線性回歸（需要 ≥5 個數據點）-----
if (dataPoints.length >= 5) {
    var m = dataPoints.length;
    var n = 7;
    var X = [], y = [];
    for (var i = 0; i < m; i++) {
        X.push(dataPoints[i].features);
        y.push([dataPoints[i].target]);
    }
    var theta = solveLinearRegression(X, y);
    if (theta) {
        var yMean = y.reduce(function(s, v) { return s + v[0]; }, 0) / m;
        var ssRes = 0, ssTot = 0;
        for (var i = 0; i < m; i++) {
            var yPred = 0;
            for (var j = 0; j < n; j++) yPred += X[i][j] * theta[j][0];
            ssRes += Math.pow(y[i][0] - yPred, 2);
            ssTot += Math.pow(y[i][0] - yMean, 2);
        }
        var rSquared = 1 - (ssRes / ssTot);
        var futureFeatures = [1, futureHour, futureIsWeekday, futureIsPeak, futureTemp, futureHum, futureIncidents];
        var forecastValue = 0;
        for (var j = 0; j < n; j++) forecastValue += futureFeatures[j] * theta[j][0];
        forecastValue = Math.max(1, Math.round(forecastValue * 10) / 10);

        prediction = {
            hasData: true,
            forecastValue: forecastValue,
            forecastTime: futureTime.toISOString(),
            forecastTimeLocal: futureTime.toLocaleString('zh-HK'),
            unit: '分鐘',
            model: {
                type: 'multivariate',
                coefficients: theta.map(function(t) { return t[0].toFixed(4); }),
                rSquared: rSquared.toFixed(4),
                dataPoints: m
            },
            method: 'multivariate_linear_regression',
            lastUpdated: new Date().toISOString()
        };
        node.warn('[預測] 多元回歸 R²=' + rSquared.toFixed(3) + '，預測值=' + forecastValue);
    }
}

// ----- 模型 2：一元線性回歸（小時 -> 平均時間），需要 2 – 4 個數據點 -----
if (!prediction.hasData && dataPoints.length >= 2) {
    // 構建 X (小時) 和 y
    var X1 = [], y1 = [];
    for (var i = 0; i < dataPoints.length; i++) {
        X1.push([1, dataPoints[i].hour]);
        y1.push([dataPoints[i].target]);
    }
    var theta1 = solveLinearRegression(X1, y1);
    if (theta1) {
        var forecastValue = theta1[0][0] + theta1[1][0] * futureHour;
        forecastValue = Math.max(1, Math.round(forecastValue * 10) / 10);
        prediction = {
            hasData: true,
            forecastValue: forecastValue,
            forecastTime: futureTime.toISOString(),
            forecastTimeLocal: futureTime.toLocaleString('zh-HK'),
            unit: '分鐘',
            model: {
                type: 'simple_linear',
                coefficients: [theta1[0][0].toFixed(4), theta1[1][0].toFixed(4)],
                dataPoints: dataPoints.length
            },
            method: 'simple_linear_regression',
            lastUpdated: new Date().toISOString()
        };
        node.warn('[預測] 一元回歸 預測值=' + forecastValue);
    }
}

// ----- 模型 3：只有一個歷史點，直接使用該點時間 -----
if (!prediction.hasData && dataPoints.length === 1) {
    var singleValue = dataPoints[0].target;
    prediction = {
        hasData: true,
        forecastValue: singleValue,
        forecastTime: futureTime.toISOString(),
        forecastTimeLocal: futureTime.toLocaleString('zh-HK'),
        unit: '分鐘',
        method: 'single_point',
        note: '歷史數據僅有一條記錄，直接使用該平均值',
        lastUpdated: new Date().toISOString()
    };
    node.warn('[預測] 單點預測 = ' + singleValue);
}

// ----- 模型 4：沒有任何歷史數據，使用實時平均行程時間 -----
if (!prediction.hasData) {
    var journeyNow = flow.get('journey_time_data');
    if (journeyNow && journeyNow.data && journeyNow.data.statistics && journeyNow.data.statistics.avg_time) {
        var currentAvg = journeyNow.data.statistics.avg_time;
        if (currentAvg > 0) {
            prediction = {
                hasData: true,
                forecastValue: currentAvg,
                forecastTime: futureTime.toISOString(),
                forecastTimeLocal: futureTime.toLocaleString('zh-HK'),
                unit: '分鐘',
                method: 'realtime_average',
                note: '尚無歷史數據，使用當前平均行程時間作爲預測',
                lastUpdated: new Date().toISOString()
            };
            node.warn('[預測] 回退爲實時平均行程時間 ' + currentAvg);
        }
    }
}

// 如果連實時數據都沒有，保持 hasData = false
if (!prediction.hasData) {
    node.warn('[預測] 無任何可用數據，無法生成預測');
}

flow.set('journey_prediction', prediction);
msg.payload = prediction;

// ---------- 輔助函數 ----------
function solveLinearRegression(X, y) {
    var m = X.length, n = X[0].length;
    var XTX = [];
    for (var i = 0; i < n; i++) XTX[i] = new Array(n).fill(0);
    for (var i = 0; i < m; i++)
        for (var j = 0; j < n; j++)
            for (var k = 0; k < n; k++)
                XTX[j][k] += X[i][j] * X[i][k];
    var XTy = new Array(n).fill(0);
    for (var i = 0; i < m; i++)
        for (var j = 0; j < n; j++)
            XTy[j] += X[i][j] * y[i][0];
    return gaussianElimination(XTX, XTy);
}

function gaussianElimination(A, b) {
    var n = A.length;
    var M = new Array(n);
    for (var i = 0; i < n; i++) {
        M[i] = A[i].slice();
        M[i].push(b[i]);
    }
    for (var k = 0; k < n; k++) {
        var maxRow = k, maxVal = Math.abs(M[k][k]);
        for (var i = k + 1; i < n; i++) {
            if (Math.abs(M[i][k]) > maxVal) { maxVal = Math.abs(M[i][k]); maxRow = i; }
        }
        if (maxVal < 1e-10) return null;
        if (maxRow !== k) { var tmp = M[k]; M[k] = M[maxRow]; M[maxRow] = tmp; }
        var pivot = M[k][k];
        for (var j = k; j <= n; j++) M[k][j] /= pivot;
        for (var i = k + 1; i < n; i++) {
            var factor = M[i][k];
            for (var j = k; j <= n; j++) M[i][j] -= factor * M[k][j];
        }
    }
    var x = new Array(n);
    for (var i = n - 1; i >= 0; i--) {
        x[i] = M[i][n];
        for (var j = i + 1; j < n; j++) x[i] -= M[i][j] * x[j];
    }
    var result = new Array(n);
    for (var i = 0; i < n; i++) result[i] = [x[i]];
    return result;
}
return msg;

