// --- 讀取各類數據 ---
var journeyData = flow.get('journey_time_data') || global.get('journey_time_data');
var slpData = global.get('slp_real_data');
var tdasData = global.get('tdas_data');
var trafficNews = global.get('traffic_news_data');
var weather = global.get('weather_latest') || {};

// 行程時間統計
var avgJourneyTime = 0, maxJourneyTime = 0;
if (journeyData && journeyData.data && journeyData.data.statistics) {
    avgJourneyTime = journeyData.data.statistics.avg_time || 0;
    maxJourneyTime = journeyData.data.statistics.max_time || 0;
}

// SLP 速度與佔用率
var avgSpeed = 0, avgOccupancy = 0;
if (slpData && slpData.statistics) {
    avgSpeed = slpData.statistics.avg_speed || 0;
    avgOccupancy = slpData.statistics.avg_occupancy || 0;
}

// TDAS 速度
var tdasSpeed = tdasData ? (tdasData.average_speed || 0) : 0;

// 綜合速度：SLP 和 TDAS 加權平均
var combinedSpeed = avgSpeed;
if (tdasSpeed > 0 && avgSpeed > 0) {
    combinedSpeed = avgSpeed * 0.6 + tdasSpeed * 0.4;
} else if (tdasSpeed > 0) {
    combinedSpeed = tdasSpeed;
}

// 活躍交通事故
var activeIncidents = trafficNews && trafficNews.statistics ? trafficNews.statistics.active : 0;

// 天氣數據
var temperature = weather.temperature != null ? weather.temperature : 25;
var humidity = weather.humidity != null ? weather.humidity : 70;
var maxRainfall = weather.maxRainfall || 0;

// --- 各項得分（0-100） ---
var speedScore = Math.min(100, Math.max(0, (combinedSpeed / 80) * 100));
var journeyScore = Math.min(100, Math.max(0, 100 - (avgJourneyTime / 30) * 100));
var occupancyScore = Math.min(100, Math.max(0, 100 - avgOccupancy * 2));
var incidentScore = Math.min(100, Math.max(0, 100 - activeIncidents * 10));

// 天氣得分：溫度偏差（基準24°C）+ 降雨扣分
var tempDeviation = Math.abs(temperature - 24);
var tempScore = Math.min(100, Math.max(0, 100 - tempDeviation * 4));
var rainScore = Math.min(100, Math.max(0, 100 - maxRainfall * 2));
var weatherScore = tempScore * 0.5 + rainScore * 0.5;

// --- 加權綜合 ---
var weights = { speed: 0.25, journey: 0.25, occupancy: 0.2, incident: 0.15, weather: 0.15 };
var tciRaw = speedScore  * weights.speed +
             journeyScore * weights.journey +
             occupancyScore * weights.occupancy +
             incidentScore * weights.incident +
             weatherScore * weights.weather;
var tciValue = Math.round(tciRaw);

// 等級與顏色
var tciLevel = 'Smooth', tciColor = '#4CAF50';
if (tciValue < 80 && tciValue >= 60) { tciLevel = 'Moderate'; tciColor = '#FF9800'; }
else if (tciValue < 60 && tciValue >= 40) { tciLevel = 'Heavy'; tciColor = '#f44336'; }
else if (tciValue < 40) { tciLevel = 'Severe'; tciColor = '#9C27B0'; }

// 準備傳給 dashboard 的數據
msg.dashboardData = {
    tci: {
        value: tciValue,
        level: tciLevel,
        color: tciColor,
        details: {
            speedScore: Math.round(speedScore),
            journeyScore: Math.round(journeyScore),
            occupancyScore: Math.round(occupancyScore),
            incidentScore: Math.round(incidentScore),
            weatherScore: Math.round(weatherScore)
        }
    },
    realtime: {
        avgSpeed: combinedSpeed,
        avgJourneyTime: avgJourneyTime,
        activeIncidents: activeIncidents,
        temperature: temperature,
        humidity: humidity,
        maxRainfall: maxRainfall,
        lastUpdate: new Date().toLocaleString('zh-HK')
    },
    journeyStats: journeyData ? journeyData.data.statistics : null,
    slpStats: slpData ? slpData.statistics : null,
    timestamp: new Date().toISOString()
};

msg.payload = msg.dashboardData;
return msg;

